#!/usr/bin/env node

import { config } from '../src/config/index.js';
import { logger } from '../src/utils/logger.js';

console.log('🔍 Testing Get Notes MCP Configuration...\n');

// 检查API密钥
if (config.auth.token) {
  console.log('✅ GET_NOTE_API_KEY is set');
  console.log(`   Key prefix: ${config.auth.token.substring(0, 8)}...`);
} else {
  console.log('❌ GET_NOTE_API_KEY is not set');
}

// 检查topic_id
if (config.knowledgeBase.topicId) {
  console.log('✅ GET_NOTE_TOPIC_ID is set');
  console.log(`   Topic ID: ${config.knowledgeBase.topicId}`);
} else {
  console.log('⚠️  GET_NOTE_TOPIC_ID is not set (optional)');
}

// 检查其他配置
console.log('\n📋 Current Configuration:');
console.log(`   API Base URL: ${config.api.baseURL}`);
console.log(`   Timeout: ${config.api.timeout}ms`);
console.log(`   Retries: ${config.api.retries}`);
console.log(`   Log Level: ${config.logging.level}`);
console.log(`   Server Name: ${config.server.name}`);
console.log(`   Server Version: ${config.server.version}`);

// 测试API连接性
console.log('\n🌐 Testing API connectivity...');

import { APIClient } from '../src/api/client.js';

const api = new APIClient();

async function testAPI() {
  try {
    // 尝试一个简单的召回操作来测试API连接
    const result = await api.recallKnowledge('test', {
      topic_id: config.knowledgeBase.topicId || 'test-topic',
      top_k: 1
    });
    
    console.log('✅ API connection test PASSED');
    console.log('✅ Authentication successful');
    
  } catch (error) {
    if (error.message.includes('topic_id') || error.message.includes('topic')) {
      console.log('✅ API connection test PASSED (expected topic validation error)');
      console.log('✅ Authentication successful');
    } else if (error.message.includes('401') || error.message.includes('Authentication')) {
      console.log('❌ API authentication failed - check your API key');
      console.log(`   Error: ${error.message}`);
    } else {
      console.log('⚠️  API test failed with unexpected error:');
      console.log(`   Error: ${error.message}`);
    }
  }
}

// 运行测试
testAPI().catch(error => {
  console.error('Test error:', error);
  process.exit(1);
});